llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Artemisinin, a structurally related sesquiterpene lactone, has poor oral bioavailability in patients due to limited solubility in water or oils; the query's polycyclic lactone scaffold with multiple hydroxyls is likely to face similar absorption limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Artemisinin is reported to have low oral bioavailability in humans, consistent with extensive first-pass metabolism and poor absorption expected for the query's multiple lactone and hydroxyl groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Artesunate, an artemisinin derivative, achieved 61% absolute oral bioavailability in Thai patients, showing that some lactone terpenoids can exceed the 20% threshold; however, the query lacks artesunate's solubilizing carboxylate group, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C51"],
      "claim": "Rosaramicin, a macrocyclic lactone antibiotic, had 39% absolute oral bioavailability in men, indicating that lactone-containing natural products can be orally bioavailable; the query lacks the basic sugar that improves rosaramicin's solubility, so this evidence is weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a complex polycyclic lactone with multiple hydroxyls and a tert-butyl group, resembling terpenoid lactones such as artemisinin, which has poor/low oral bioavailability in humans. The most structurally relevant evidence supports low F (<20%), while high-F evidence comes from structurally distant compounds with low transferability. Therefore, low oral bioavailability is predicted.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query or close analogues; all retrieved molecules have Morgan similarity <0.18.",
    "Artemisinin's quantitative F is not reported in the retrieved records; only qualitative 'low/poor' labels are available.",
    "The effect of the tert-butyl group and multiple lactones on solubility and first-pass metabolism is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

